import java.util.Optional;

public class Users {
  static Optional<String> findUser(long id) {
    if (id <= 0) return Optional.empty();
    return Optional.of("user-" + id);
  }
}

import java.util.ArrayDeque;

public class Stack<T> {
  private final ArrayDeque<T> items = new ArrayDeque<>();
  public void push(T value) { items.push(value); }
  public T pop() { return items.poll(); }
}

import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

public class Grouping {
  static <T, K> Map<K, List<T>> groupBy(List<T> items, Function<T, K> keyFn) {
    return items.stream().collect(Collectors.groupingBy(keyFn));
  }
}

public sealed interface Result<T> permits Result.Ok, Result.Err {
  record Ok<T>(T value) implements Result<T> {}
  record Err<T>(String message) implements Result<T> {}
}

public final class Retry {
  public static <T> T run(int attempts, Callable<T> fn) throws Exception {
    Exception last = null;
    for (int i = 0; i < attempts; i++) {
      try {
        return fn.call();
      } catch (Exception ex) {
        last = ex;
      }
    }
    throw last;
  }
}

public record Page<T>(List<T> items, boolean hasNext) {
  public static <T> Page<T> empty() {
    return new Page<>(List.of(), false);
  }
}
